def _sd_class(hole_strs):
    r = "23456789TJQKA"
    a, b = hole_strs[0], hole_strs[1]
    ra, rb = a[0].upper(), b[0].upper()
    if r.index(ra) < r.index(rb):
        ra, rb, a, b = rb, ra, b, a
    if ra == rb:
        return ra + rb
    return ra + rb + ("s" if a[1].lower() == b[1].lower() else "o")


def _sd_eq_set(idx, mixes):
    """Equity of hand index `idx` vs independent opponents, each a mixture over the 4 primitives."""
    n = len(mixes)
    if n == 0:
        return 1.0
    if n > 3:
        # extrapolate: eq_n ~ eq_3 * (eq_3 / eq_2) ** (n - 3), using the three tightest-looking opponents
        e3 = _sd_eq_set(idx, mixes[:3])
        e2 = _sd_eq_set(idx, mixes[:2])
        ratio = min(1.0, e3 / e2) if e2 > 0 else 0.5
        return e3 * ratio ** (n - 3)
    total = 0.0
    if n == 1:
        m0 = mixes[0]
        for a in range(4):
            if m0[a]:
                total += m0[a] * _SD_EQ[str(a)][idx]
        return total
    if n == 2:
        m0, m1 = mixes
        for a in range(4):
            if not m0[a]:
                continue
            for b in range(4):
                if m1[b]:
                    key = "".join(sorted(str(a) + str(b)))
                    total += m0[a] * m1[b] * _SD_EQ[key][idx]
        return total
    m0, m1, m2 = mixes
    for a in range(4):
        if not m0[a]:
            continue
        for b in range(4):
            if not m1[b]:
                continue
            wab = m0[a] * m1[b]
            for c in range(4):
                if m2[c]:
                    key = "".join(sorted(str(a) + str(b) + str(c)))
                    total += wab * m2[c] * _SD_EQ[key][idx]
    return total


def _sd_situation(state):
    """Return (jammer, callers, behind, raisers_behind, n_raises_before_jam) for the current street."""
    me = state.get("seat", 0)
    folded = state.get("folded") or []
    n = len(folded)
    bets = S(state, "bets") or [0] * n
    all_in = state.get("all_in") or [False] * n
    stacks = S(state, "stacks") or [0] * n
    hist = S(state, "history") or []
    street = S(state, "street") or ("preflop" if not state.get("board") else None)
    raises = []
    for ev in hist:
        if isinstance(ev, dict) and ev.get("action") == "raise" and (street is None or ev.get("street") == street):
            raises.append(ev.get("seat"))
    cur = max(bets) if bets else 0
    jammer = raises[-1] if raises else None
    if jammer is None or jammer == me or not (0 <= jammer < n):
        cands = [i for i in range(n) if i != me and not folded[i] and bets[i] == cur]
        jammer = cands[0] if cands else None
    n_before = max(0, len(raises) - 1)
    earlier_raisers = set(s for s in raises[:-1] if s is not None)
    callers, behind, raisers_behind = [], [], []
    for i in range(n):
        if i == me or i == jammer or folded[i]:
            continue
        if bets[i] >= cur or all_in[i] or stacks[i] == 0:
            callers.append(i)
        elif i in earlier_raisers:
            raisers_behind.append(i)
        else:
            behind.append(i)
    return jammer, callers, behind, raisers_behind, n_before


def _sd_preflop(agent, state, ctx):
    legal = S(state, "legal_actions", []) or []
    hole = S(state, "hole_cards")
    idx = _SD_IDX.get(_sd_class(hole))
    if idx is None:
        return None
    me = state.get("seat", 0)
    stacks = S(state, "stacks")
    bets = S(state, "bets")
    to_call = S(state, "to_call", 0) or 0
    pot = S(state, "pot")
    if pot is None:
        pot = sum(bets) if bets else 0
    my_stack = stacks[me] if stacks else to_call
    call_amt = min(to_call, my_stack) if my_stack else to_call
    jammer, callers, behind, raisers_behind, n_before = _sd_situation(state)
    jam_mix = _SD_MIX_OPEN_JAM if n_before == 0 else _SD_MIX_REJAM
    base = [jam_mix] + [_SD_MIX_CALLER] * len(callers)
    cur = max(bets) if bets else to_call
    # overcall events from behind: probability per player, amount each would add
    others = [(i, _SD_Q_BEHIND) for i in behind] + [(i, _SD_Q_RAISER_BEHIND) for i in raisers_behind]
    probs = [1.0]  # distribution of number of overcallers (cap at 2)
    add_amt = []
    for i, q in others:
        new = [0.0] * min(len(probs) + 1, 3)
        for k, p in enumerate(probs):
            new[k] += p * (1 - q)
            new[min(k + 1, 2)] += p * q
        probs = new
        a = cur - (bets[i] if bets else 0)
        if stacks:
            a = min(a, stacks[i])
        add_amt.append(max(0, a))
    avg_add = (sum(add_amt) / len(add_amt)) if add_amt else 0
    ev = 0.0
    for k, p in enumerate(probs):
        if p <= 0:
            continue
        eq = _sd_eq_set(idx, base + [_SD_MIX_CALLER] * k)
        final_pot = pot + call_amt + k * avg_add
        ev += p * (eq * final_pot - call_amt)
    ctx["sd_ev"] = ev
    # stack-sized raise that is not all-in and we can re-raise: jam the top of our calling range
    if "raise" in legal and state.get("max_raise_to") is not None and ev > 0:
        eq_hu = _sd_eq_set(idx, base)
        if eq_hu >= 0.62:
            return {"action": "raise", "amount": int(state["max_raise_to"])}
    if ev > _SD_MARGIN * call_amt and "call" in legal:
        return {"action": "call"}
    return {"action": "check"} if "check" in legal else {"action": "fold"}


def _sd_strong(hole2, board):
    """Made-hand filter on the current board: two pair+, or a pair using a hole card at/above 2nd board rank,
    or a flush draw (4 to a suit using a hole card)."""
    v = _evaluate(hole2 + board)
    cat = v >> 20
    if cat >= 2:
        # discount board-only two pair/trips: require a hole card to matter
        bv = _evaluate(board) if len(board) >= 5 else -1
        return v != bv
    if cat == 1:
        pr = (v >> 16) & 15
        brs = sorted((c >> 2 for c in board), reverse=True)
        uses_hole = any((c >> 2) == pr for c in hole2)
        return uses_hole and len(brs) >= 2 and pr >= brs[1]
    suits = [c & 3 for c in board]
    for c in hole2:
        if suits.count(c & 3) + sum(1 for d in hole2 if d & 3 == c & 3) >= 4:
            return True
    return False


def _sd_postflop(agent, state, ctx):
    legal = S(state, "legal_actions", []) or []
    hole, board = ctx["hole"], ctx["board"]
    me = state.get("seat", 0)
    stacks = S(state, "stacks")
    to_call = S(state, "to_call", 0) or 0
    pot = S(state, "pot")
    bets = S(state, "bets")
    if pot is None:
        pot = sum(bets) if bets else to_call
    my_stack = stacks[me] if stacks else to_call
    call_amt = min(to_call, my_stack) if my_stack else to_call
    jammer, callers, behind, raisers_behind, _ = _sd_situation(state)
    opp_w = [_SD_POST_W_JAMMER] + [_SD_POST_W_CALLER] * len(callers)  # P(hand is random) vs made-hand range
    opp_w = opp_w[:4]
    # private RNG (do not consume the shared agent.rng stream used by the default policy)
    rng = random.Random(hash((tuple(hole), tuple(board), call_amt, pot)) & 0xFFFFFFFF)
    known = set(hole + board)
    deck = [c for c in range(52) if c not in known]
    missing = 5 - len(board)
    share = 0.0
    nsamp = 0
    deadline = time.perf_counter() + _SD_POST_BUDGET
    for _ in range(_SD_POST_SAMPLES):
        if nsamp >= 30 and time.perf_counter() > deadline:
            break
        avail = deck[:]
        rng.shuffle(avail)
        pos = 0
        opps = []
        ok = True
        for w in opp_w:
            if rng.random() < w:
                opps.append(avail[pos:pos + 2])
                pos += 2
            else:
                got = None
                for _try in range(12):
                    if pos + 2 > len(avail):
                        break
                    h2 = avail[pos:pos + 2]
                    if _sd_strong(h2, board):
                        got = h2
                        pos += 2
                        break
                    # recycle: move the rejected pair to the end so cards stay available
                    avail.append(avail.pop(pos))
                    avail.append(avail.pop(pos))
                if got is None:
                    got = avail[pos:pos + 2]
                    pos += 2
                opps.append(got)
        if pos + missing > len(avail):
            continue
        complete = board + avail[pos:pos + missing]
        hs = _evaluate(hole + complete)
        best, ties, mine = hs, 1, True
        for o in opps:
            v = _evaluate(o + complete)
            if v > best:
                best, mine, ties = v, False, 1
            elif v == best:
                ties += 1
        if mine:
            share += 1.0 / ties
        nsamp += 1
    if not nsamp:
        return None
    eq = share / nsamp
    need = call_amt / (pot + call_amt) if pot + call_amt > 0 else 0.5
    need += 0.03 * len(behind) + 0.06 * len(raisers_behind)
    ctx["sd_eq"] = eq
    if "raise" in legal and state.get("max_raise_to") is not None and eq >= 0.70:
        return {"action": "raise", "amount": int(state["max_raise_to"])}
    if eq >= need and "call" in legal:
        return {"action": "call"}
    return {"action": "check"} if "check" in legal else {"action": "fold"}


def _cand_facing_allin(agent, state, ctx):
    """HOOK: facing_allin — balanced shove-defense (fixed range model, no per-opponent adaptation)."""
    try:
        if not ctx.get("board"):
            return _sd_preflop(agent, state, ctx)
        return _sd_postflop(agent, state, ctx)
    except Exception:
        return None


# ---- plug-in from tournament/preflop-structure/minimal.py ----
_PF_EQ_STR = ("")


def _pf_build_table():
    table = {}
    pos = 0
    for hi in range(12, -1, -1):
        for lo in range(hi, -1, -1):
            for suited in ((False,) if hi == lo else (True, False)):
                table[(hi, lo, suited)] = int(_PF_EQ_STR[pos:pos + 3]) / 1000.0
                pos += 3
    return table


_PF_EQ = _pf_build_table()


def _pf_equity(hole):
    """Heads-up equity vs a random hand for two card ints (rank = c >> 2, suit = c & 3)."""
    r1, r2 = hole[0] >> 2, hole[1] >> 2
    hi, lo = max(r1, r2), min(r1, r2)
    return _PF_EQ[(hi, lo, hi != lo and (hole[0] & 3) == (hole[1] & 3))]


_PF_OPEN_LATE = 0.565


_PF_OPEN_MID = 0.590


_PF_OPEN_EARLY = 0.610


_PF_OPEN_SB = 0.575


_PF_VALUE_3BET = 0.655


def _pf_raise(state, total):
    if "raise" not in (S(state, "legal_actions", []) or []):
        return None
    return {"action": "raise", "amount": int(total)}


def _pf_call_or_check(state):
    legal = S(state, "legal_actions", []) or []
    return {"action": "call"} if "call" in legal else {"action": "check"}


def _pf_fold_or_check(state):
    legal = S(state, "legal_actions", []) or []
    return {"action": "check"} if "check" in legal else {"action": "fold"}


def _cand_preflop(agent, state, ctx):
    """HOOK: preflop — preflop decisions other than facing all-in.
    Minimal patch: replace the 32-sample win rate vs ALL opponents with a heads-up equity table,
    position-based open thresholds, a fixed open / iso size, and simple call / 3-bet rules."""
    bets = S(state, "bets")
    stacks = S(state, "stacks")
    bb = S(state, "big_blind", 20) or 20
    to_call = S(state, "to_call", 0) or 0
    me = state.get("seat", getattr(agent, "seat", 0))
    if not bets or not stacks or me is None or me >= len(bets):
        return None  # cannot read the table structure: defer to the incumbent
    my_stack = stacks[me]
    if to_call > 0 and to_call >= 0.5 * my_stack:
        return None  # facing (near) all-in belongs to hook_facing_allin / incumbent
    n = len(bets)
    button = S(state, "button")
    pos = (me - button) % n if button is not None else 4
    hole = ctx["hole"]
    e = _pf_equity(hole)
    pair = (hole[0] >> 2) == (hole[1] >> 2)
    cur = max(bets)
    folded = state.get("folded") or [False] * n
    my_bet = bets[me]
    eff = my_stack + my_bet  # chips I can put in this hand (street total)

    if cur <= bb:
        # Unopened or limped pot.
        bb_seat = (button + 2) % n if button is not None else None
        limpers = sum(1 for i in range(n) if i != me and i != bb_seat and not folded[i] and bets[i] >= bb)
        if pos == 0 or pos >= n - 1:
            thr = _PF_OPEN_LATE
        elif pos == 1:
            thr = _PF_OPEN_SB
        elif pos == 2:
            thr = _PF_OPEN_SB  # BB: raise for value / iso
        elif pos >= n - 3:
            thr = _PF_OPEN_MID
        else:
            thr = _PF_OPEN_EARLY
        thr += 0.01 * limpers  # isolate a bit tighter behind limpers (they call raises)
        if e >= thr:
            size = 3 * bb + bb * limpers + (bb if pos in (1, 2) else 0)
            act = _pf_raise(state, min(size, eff))
            if act is not None:
                return act
            return _pf_call_or_check(state)
        if to_call == 0:
            return {"action": "check"}
        # Cheap entry: over-limp / complete with pairs and decent hands when others limped.
        if limpers >= 1 and (pair or e >= 0.54) and to_call <= bb:
            return _pf_call_or_check(state)
        if pos == 1 and e >= 0.52 and to_call <= bb // 2 + 1:
            return _pf_call_or_check(state)
        return _pf_fold_or_check(state)

    # Facing a raise (not near all-in).
    raises = 0
    for ev in (S(state, "history") or []):
        if isinstance(ev, dict) and ev.get("action") == "raise" and ev.get("street", "preflop") == "preflop":
            raises += 1
    raises = max(raises, 1)
    callers = max(0, sum(1 for i in range(n) if i != me and not folded[i] and bets[i] >= cur) - 1)
    if raises == 1:
        if (e >= _PF_VALUE_3BET and not pair) or (pair and hole[0] >> 2 >= 6):  # AQs+, AKo; 88+
            size = 3 * cur + cur * callers
            if size >= 0.4 * eff:  # do not leave an awkward stack behind: shove instead
                size = eff
            act = _pf_raise(state, min(size, eff))
            return act if act is not None else _pf_call_or_check(state)
        price = to_call / float(bb)
        if price <= 1.01 and e >= 0.45:  # e.g. BB vs a min-raise
            return _pf_call_or_check(state)
        call_thr = 0.585 if price <= 3 else (0.61 if price <= 6 else 0.635)
        if e >= call_thr and to_call <= 0.12 * eff:
            return _pf_call_or_check(state)
        if pair and to_call <= 0.06 * eff:  # set-mine cheaply
            return _pf_call_or_check(state)
        return _pf_fold_or_check(state)
    # Facing a 3-bet or more.
    if (pair and hole[0] >> 2 >= 10) or (not pair and e >= 0.67):  # QQ+, AKs: get it in
        act = _pf_raise(state, state.get("max_raise_to") or eff)
        return act if act is not None else _pf_call_or_check(state)
    if ((pair and hole[0] >> 2 >= 8) or (not pair and e >= 0.655)) and to_call <= 0.25 * eff:  # TT-JJ, AKo, AQs: call
        return _pf_call_or_check(state)
    return _pf_fold_or_check(state)


# ---- plug-in from tournament/multiway-awareness/minimal.py ----
_MW_THRESH = {1: 0.62, 2: 0.53, 3: 0.46}


_MW_THRESH_MANY = 0.42


_MW_MONSTER = 0.85


_MW_VALUE_FRAC = 0.6


_MW_SAMPLES = 32


_MW_SECONDS = 0.0004


def _mw_threshold(n):
    return _MW_THRESH.get(n, _MW_THRESH_MANY)


def _cand_betting_mw(agent, state, ctx):
    """HOOK: betting — postflop when nothing to call (to_call == 0): check, value bet or bluff.
    Use agent.size(state, ctx, intent, default_frac) for amounts.

    multiway-awareness/minimal: bet for value only when the win rate vs the live opponents clears a
    threshold that rises (relative to fair share) with the number of opponents; never bluff."""
    legal = S(state, "legal_actions", []) or []
    n = ctx.get("opponents", 0)
    if "raise" not in legal or n <= 1:
        return None   # heads-up: defer to the incumbent (this patch only changes multiway spots)
    win_rate, samples = _estimate_win_rate(ctx["hole"], ctx["board"], n, agent.rng,
                                           deadline=ctx["started"] + _MW_SECONDS, max_samples=_MW_SAMPLES)
    agent.last_samples = samples
    ctx["win_rate"] = win_rate
    if win_rate > _MW_MONSTER:
        return {"action": "raise", "amount": int(state["max_raise_to"])}
    if win_rate >= _mw_threshold(n):
        return {"action": "raise", "amount": agent.size(state, ctx, "value", _MW_VALUE_FRAC)}
    return {"action": "check"} if "check" in legal else None


# ===========================================================================================
# autopicker-lc LAYERS 2-4: opponent profiles -> personalities -> auto picker (4 states) -> safety nets
# Layer 1 (baseline) = tournament plug-ins (_cand_*) + the baseline rules in the hooks below.
# Every exploit is a hypothesis; the picker only leans on it in proportion to evidence.
# ===========================================================================================
import collections as _v1_col
import math as _v1_math

_V1_STATS = ("vpip", "pfr", "shove", "aggr", "fold_vs_bet")
_V1_PRIOR = {"vpip": 0.30, "pfr": 0.15, "shove": 0.02, "aggr": 0.35, "fold_vs_bet": 0.45}
_V1_PRIOR_K = 12.0          # prior strength (pseudo-observations)
_V1_RECENT = 30             # recent window per stat
_V1_DECAY = 0.997           # long-run decay per observation (forgets slowly)
_V1_Z_ENTER = 3.0           # surprise needed to enter DEVIATING
_V1_Z_EXIT = 1.5            # surprise below which DEVIATING relaxes back
_V1_CHANGE_HANDS = 40       # DEVIATING this long (seat-hands) => CHANGED (relearn)
_V1_CONF_K = 30.0           # confidence = hands / (hands + K)
_V1_STOP_HANDS = 40         # stop-loss window (attributed hands)
_V1_STOP_BB = -150.0        # stop-loss threshold over the window, in big blinds
_V1_STOP_COOLDOWN = 60      # hands with exploits off after the stop-loss fires
_V1_MC_SECONDS = 0.0003     # equity sampling budget per decision (review #12: match v1-fast thinking time)

_V1_USE_EXPLOIT = False
_V1_USE_PICKER = True       # False => personalities only, no deviation states / stop-loss (ablation)

IN_CHARACTER, DEVIATING, CHANGED, REACTIVE = "in_character", "deviating", "changed", "reactive"

# Response settings ("knobs"). jam_width: assumed width of their all-in range (0..1);
# bet_f: multiplier on the width of their betting range; bluff_r: share of random hands in their aggression;
# value_mult: our value-size multiplier vs them; bluff_ok: how willing we are to bluff them (0..1).
_V1_K0 = {"jam_width": 0.5, "bet_f": 1.0, "bluff_r": 0.12, "value_mult": 1.0, "bluff_ok": 0.5}
_V1_PERSONALITY_KNOBS = {
    "shover":        {"jam_width": 1.0, "bet_f": 1.6, "bluff_r": 0.40, "value_mult": 1.3, "bluff_ok": 0.0},
    "maniac":        {"jam_width": 0.8, "bet_f": 1.8, "bluff_r": 0.45, "value_mult": 1.2, "bluff_ok": 0.2},
    "station":       {"jam_width": 0.6, "bet_f": 1.2, "bluff_r": 0.10, "value_mult": 1.6, "bluff_ok": 0.0},
    "nit":           {"jam_width": 0.12, "bet_f": 0.5, "bluff_r": 0.03, "value_mult": 0.6, "bluff_ok": 1.0},
    "tight_passive": {"jam_width": 0.15, "bet_f": 0.45, "bluff_r": 0.03, "value_mult": 0.8, "bluff_ok": 0.8},
    "loose_passive": {"jam_width": 0.5, "bet_f": 0.7, "bluff_r": 0.05, "value_mult": 1.4, "bluff_ok": 0.2},
    "folder":        {"jam_width": 0.3, "bet_f": 0.8, "bluff_r": 0.10, "value_mult": 0.8, "bluff_ok": 1.0},
    "balanced":      dict(_V1_K0),
    "unknown":       dict(_V1_K0),
}
# Out-of-character pool: responses chosen by the DIRECTION of the deviation (uses what we knew before).
_V1_OOC_POOL = {
    "aggression_up_respect":  {"jam_width": 0.25, "bet_f": 0.7, "bluff_r": 0.08, "value_mult": 1.0, "bluff_ok": 0.3},
    "aggression_up_calldown": {"jam_width": 0.7, "bet_f": 1.6, "bluff_r": 0.35, "value_mult": 1.1, "bluff_ok": 0.2},
    "tightening":             {"jam_width": 0.2, "bet_f": 0.5, "bluff_r": 0.05, "value_mult": 0.8, "bluff_ok": 0.8},
    "loosening":              {"jam_width": 0.6, "bet_f": 1.1, "bluff_r": 0.12, "value_mult": 1.3, "bluff_ok": 0.1},
    "robust":                 {"jam_width": 0.4, "bet_f": 1.0, "bluff_r": 0.20, "value_mult": 1.0, "bluff_ok": 0.3},
}
_V1_STATE_WEIGHT = {IN_CHARACTER: 1.0, DEVIATING: 0.6, CHANGED: 0.3, REACTIVE: 0.3}


class _V1Seat:
    def __init__(self):
        self.n = {s: 0.0 for s in _V1_STATS}      # decayed opportunities
        self.k = {s: 0.0 for s in _V1_STATS}      # decayed successes
        self.recent = {s: _v1_col.deque(maxlen=_V1_RECENT) for s in _V1_STATS}
        self.hands = 0
        self.state = IN_CHARACTER
        self.dev_since = None
        self.dev_direction = None
        self.calm_updates = 0
        self.showdowns = _v1_col.deque(maxlen=40)   # (strength 0..1, was_aggressor, hand_index)
        self.aggr_vs_me = _v1_col.deque(maxlen=_V1_RECENT)
        self.aggr_vs_field = _v1_col.deque(maxlen=_V1_RECENT)
        self.results = _v1_col.deque(maxlen=_V1_STOP_HANDS)  # our bb result in hands attributed to this seat
        self.stop_until = -1
        self.label = "unknown"
        self.pending_label, self.pending_count = None, 0
        self.history_states = _v1_col.deque(maxlen=20)

    def add(self, stat, x):
        self.n[stat] = self.n[stat] * _V1_DECAY + 1.0
        self.k[stat] = self.k[stat] * _V1_DECAY + (1.0 if x else 0.0)
        self.recent[stat].append(1 if x else 0)

    def rate(self, stat):
        return (self.k[stat] + _V1_PRIOR[stat] * _V1_PRIOR_K) / (self.n[stat] + _V1_PRIOR_K)

    def recent_rate(self, stat):
        r = self.recent[stat]
        return (sum(r) / len(r)) if r else None


class V1Profiles:
    """Layer 2: one shared stat profile per opponent seat, fed by the kit event layer."""

    def __init__(self):
        self.seats = {}
        self.me = None
        self.hand_index = 0
        self.big_blind = 20
        self.stack = 2000
        self._reset_hand()

    def _reset_hand(self):
        self.street = "preflop"
        self.facing_bet = False
        self.vpip_done = set()
        self.pfr_done = set()
        self.acted_pf = set()
        self.last_aggr = None           # (seat, street)
        self.board = []
        self.in_hand = set()            # seats that put voluntary chips in
        self.we_in = False

    def seat(self, s):
        if s not in self.seats:
            self.seats[s] = _V1Seat()
        return self.seats[s]

    # -------- events --------
    def observe(self, ev):
        t = ev.get("type")
        if t == "hand_start":
            self._reset_hand()
            self.hand_index += 1
            for s in range(len(ev.get("stacks") or [])):
                if s != self.me:
                    self.seat(s).hands += 1
        elif t == "board":
            self.street = ev.get("street", self.street)
            if ev.get("board"):
                self.board = list(ev["board"])
            self.facing_bet = False
        elif t == "action":
            self._on_action(ev)
        elif t == "showdown":
            self._on_showdown(ev)
        elif t == "hand_end":
            self._on_hand_end(ev)

    def _on_action(self, ev):
        seat, a = ev.get("seat"), ev.get("action")
        if seat is None or a in (None, "post", "small_blind", "big_blind"):
            return
        street = ev.get("street", self.street)
        if seat == self.me:
            if a in ("call", "raise"):
                self.we_in = True
            if a == "raise":
                self.facing_bet = True
                self.last_aggr = (seat, street)
            return
        st = self.seat(seat)
        if street == "preflop":
            if seat not in self.acted_pf:
                self.acted_pf.add(seat)
                st.add("vpip", a in ("call", "raise"))
                st.add("pfr", a == "raise")
                st.add("shove", a == "raise" and (ev.get("amount") or 0) >= 0.9 * self.stack)
            if a in ("call", "raise"):
                self.in_hand.add(seat)
        else:
            if a in ("raise", "call", "check"):
                st.add("aggr", a == "raise")
                (st.aggr_vs_me if self.we_in else st.aggr_vs_field).append(1 if a == "raise" else 0)
        if self.facing_bet and a in ("fold", "call", "raise"):
            st.add("fold_vs_bet", a == "fold")
        if a == "raise":
            self.facing_bet = True
            self.last_aggr = (seat, street)

    def _on_showdown(self, ev):
        hands = ev.get("hands") or {}
        board = self.board
        if len(board) < 5:
            return
        for seat, cards in hands.items():
            seat = int(seat)
            if seat == self.me or not cards:
                continue
            strength = _v1_strength(cards, board)
            was_aggr = bool(self.last_aggr and self.last_aggr[0] == seat)
            self.seat(seat).showdowns.append((strength, was_aggr, self.hand_index))

    def _on_hand_end(self, ev):
        deltas = ev.get("deltas") or []
        if self.me is not None and self.me < len(deltas) and self.we_in:
            bb = self.big_blind or 20
            mine = deltas[self.me] / bb
            # attribute our result to the opponent who won/lost most against us this hand
            opp = None
            if self.last_aggr and self.last_aggr[0] != self.me:
                opp = self.last_aggr[0]
            elif self.in_hand:
                opp = max(self.in_hand, key=lambda s: abs(deltas[s]) if s < len(deltas) else 0)
            if opp is not None:
                self.seat(opp).results.append(mine)
        for s, st in self.seats.items():
            self._update_state(s, st)

    # -------- layer 3: personality labels --------
    def classify(self, st):
        vpip, pfr, shove = st.rate("vpip"), st.rate("pfr"), st.rate("shove")
        aggr, fold = st.rate("aggr"), st.rate("fold_vs_bet")
        if st.hands < 8:
            return "unknown"
        if shove > 0.30:
            return "shover"
        if aggr > 0.55 or pfr > 0.35:
            return "maniac"
        if vpip > 0.45 and aggr < 0.25 and fold < 0.30:
            return "station"
        if vpip < 0.15:
            return "nit"
        if vpip < 0.30 and aggr < 0.25:
            return "tight_passive"
        if vpip > 0.40 and pfr < 0.10:
            return "loose_passive"
        if fold > 0.65:
            return "folder"
        return "balanced"

    # -------- layer 4: auto picker (surprise score + 4 states) --------
    def surprise(self, st):
        best, direction = 0.0, None
        for s in _V1_STATS:
            r = st.recent[s]
            if len(r) < 10:
                continue
            q = sum(r) / len(r)
            p = min(0.97, max(0.03, st.rate(s)))
            z = (q - p) / _v1_math.sqrt(p * (1 - p) / len(r))
            if abs(z) > abs(best):
                best, direction = z, (s, "up" if z > 0 else "down")
        return abs(best), direction

    def _reactive(self, st):
        a, b = st.aggr_vs_me, st.aggr_vs_field
        if len(a) < 12 or len(b) < 12:
            return False
        pa, pb = sum(a) / len(a), sum(b) / len(b)
        p = min(0.97, max(0.03, (sum(a) + sum(b)) / (len(a) + len(b))))
        z = (pa - pb) / _v1_math.sqrt(p * (1 - p) * (1 / len(a) + 1 / len(b)))
        return z > 3.0

    def _update_state(self, seat, st):
        z, direction = self.surprise(st)
        if st.state in (IN_CHARACTER, CHANGED, REACTIVE):
            if self._reactive(st):
                st.state = REACTIVE
            elif z >= _V1_Z_ENTER:
                st.state, st.dev_since, st.dev_direction, st.calm_updates = DEVIATING, st.hands, direction, 0
            elif st.state != IN_CHARACTER and z < _V1_Z_EXIT:
                st.state = IN_CHARACTER
        elif st.state == DEVIATING:
            if z < _V1_Z_EXIT:
                st.calm_updates += 1
                if st.calm_updates >= 3:           # it was noise: back to the personality
                    st.state = IN_CHARACTER
            else:
                st.calm_updates = 0
                if direction:
                    st.dev_direction = direction
                if st.hands - (st.dev_since or st.hands) >= _V1_CHANGE_HANDS:
                    self._relearn(st)              # persistent: a real change, relearn the bot
        new = self.classify(st)
        if new == st.label or st.label == "unknown" or st.state == CHANGED:
            st.label, st.pending_label, st.pending_count = new, None, 0
        elif new == st.pending_label:
            st.pending_count += 1
            if st.pending_count >= 3:                 # label hysteresis: must persist 3 updates
                st.label, st.pending_label, st.pending_count = new, None, 0
        else:
            st.pending_label, st.pending_count = new, 1
        st.history_states.append(st.state)
        # stop-loss
        if len(st.results) >= 15 and sum(st.results) <= _V1_STOP_BB and st.stop_until < self.hand_index:
            st.stop_until = self.hand_index + _V1_STOP_COOLDOWN
            st.results.clear()

    def _relearn(self, st):
        for s in _V1_STATS:
            r = st.recent[s]
            st.n[s] = float(len(r))
            st.k[s] = float(sum(r))
        st.showdowns = _v1_col.deque([x for x in st.showdowns if x[2] >= self.hand_index - 30], maxlen=40)
        st.state, st.dev_since, st.dev_direction = CHANGED, None, None

    # -------- knobs: blended response settings for one opponent --------
    def knobs(self, seat):
        st = self.seats.get(seat)
        if st is None or not _V1_USE_EXPLOIT:
            return dict(_V1_K0), 0.0, "unknown", IN_CHARACTER
        if not _V1_USE_PICKER:
            conf = st.hands / (st.hands + _V1_CONF_K)
            target = _V1_PERSONALITY_KNOBS.get(st.label, _V1_K0)
            return ({key: _V1_K0[key] + conf * (target[key] - _V1_K0[key]) for key in _V1_K0}, conf, st.label,
                    IN_CHARACTER)
        conf = st.hands / (st.hands + _V1_CONF_K)
        w = conf * _V1_STATE_WEIGHT.get(st.state, 0.3)
        if st.stop_until >= self.hand_index:
            w = 0.0
        if st.state == DEVIATING:
            target = _V1_OOC_POOL[self._ooc_choice(st)]
        else:
            target = _V1_PERSONALITY_KNOBS.get(st.label, _V1_K0)
        k = {key: _V1_K0[key] + w * (target[key] - _V1_K0[key]) for key in _V1_K0}
        # bluff share from showdowns (mixture model): junk shown after being the aggressor
        aggr_sd = [s for s, was_aggr, _ in st.showdowns if was_aggr]
        if len(aggr_sd) >= 4:
            junk = sum(1 for s in aggr_sd if s < 0.45) / len(aggr_sd)
            m = len(aggr_sd) / (len(aggr_sd) + 8.0)
            k["bluff_r"] = (1 - m) * k["bluff_r"] + m * junk
        return k, w, st.label, st.state

    def _ooc_choice(self, st):
        d = st.dev_direction
        if not d:
            return "robust"
        stat, way = d
        if stat in ("aggr", "pfr", "shove") and way == "up":
            junk_since = [s for s, was_aggr, h in st.showdowns
                          if was_aggr and st.dev_since is not None and h >= self.hand_index - (st.hands - st.dev_since)]
            if sum(1 for s in junk_since if s < 0.45) >= 2:
                return "aggression_up_calldown"
            return "aggression_up_respect"
        if (stat == "vpip" and way == "down") or (stat in ("aggr", "pfr") and way == "down"):
            return "tightening"
        if (stat == "vpip" and way == "up") or (stat == "fold_vs_bet" and way == "down"):
            return "loosening"
        if stat == "fold_vs_bet" and way == "up":
            return "tightening"
        return "robust"

    def fold_prob(self, seat):
        st = self.seats.get(seat)
        return st.rate("fold_vs_bet") if st else _V1_PRIOR["fold_vs_bet"]

    def describe(self):
        return {s: {"label": st.label, "state": st.state, "hands": st.hands,
                    "vpip": round(st.rate("vpip"), 2), "aggr": round(st.rate("aggr"), 2),
                    "fold_vs_bet": round(st.rate("fold_vs_bet"), 2), "shove": round(st.rate("shove"), 2)}
                for s, st in sorted(self.seats.items())}


EXTRA_TRACKERS.append(V1Profiles)


# -------- shared helpers (equity vs ranges within the time budget) --------
def _v1_strength(cards, board, samples=40):
    """Fraction of random opponent holdings that this hand beats on the final board (ties = half)."""
    try:
        h = [_card(c) for c in cards]
        b = [_card(c) for c in board[:5]]
        dead = set(h) | set(b)
        deck = [c for c in range(52) if c not in dead]
        me = _evaluate(h + b)
        rng = random.Random(hash(tuple(h + b)) & 0xFFFF)
        score = 0.0
        for _ in range(samples):
            o = rng.sample(deck, 2)
            v = _evaluate(o + b)
            score += 1.0 if me > v else (0.5 if me == v else 0.0)
        return score / samples
    except Exception:
        return 0.5


def _v1_class_pct():
    """Percentile (0 = best) of each 169 hand class by heads-up equity, weighted by combos."""
    items = []
    R = "23456789TJQKA"
    for key, eq in _PF_EQ.items():
        if isinstance(key, tuple):                        # (high rank, low rank, suited)
            hi, lo, suited = key
            key = R[hi] * 2 if hi == lo else R[hi] + R[lo] + ("s" if suited else "o")
        combos = 6 if len(key) == 2 else (4 if key.endswith("s") else 12)
        items.append((eq, key, combos))
    items.sort(reverse=True)
    out, cum = {}, 0
    for eq, key, combos in items:
        out[key] = (cum + combos / 2.0) / 1326.0
        cum += combos
    return out


try:
    _V1_PCT = _v1_class_pct()
except Exception:
    _V1_PCT = {}


def _v1_key(c1, c2):
    r1, r2 = c1 >> 2, c2 >> 2
    if r1 < r2:
        r1, r2, c1, c2 = r2, r1, c2, c1
    R = "23456789TJQKA"
    if r1 == r2:
        return R[r1] * 2
    return R[r1] + R[r2] + ("s" if (c1 & 3) == (c2 & 3) else "o")


def _v1_equity(hole, board, ranges, rng, deadline, max_samples=36):
    """MC equity vs a list of (width f, random share r) ranges, one per live opponent. Ties = split."""
    known = set(hole + board)
    deck = [c for c in range(52) if c not in known]
    missing = 5 - len(board)
    total = 0.0
    n = 0
    for _ in range(max_samples):
        if n >= 4 and time.perf_counter() >= deadline:
            break
        avail = deck[:]
        rng.shuffle(avail)
        idx = 0
        opps = []
        ok = True
        for f, r in ranges:
            got = None
            for _try in range(8):
                if idx + 2 > len(avail):
                    break
                c1, c2 = avail[idx], avail[idx + 1]
                idx += 2
                if f >= 0.999 or rng.random() < r or _V1_PCT.get(_v1_key(c1, c2), 0.5) <= f:
                    got = [c1, c2]
                    break
            if got is None:
                ok = False
                break
            opps.append(got)
        if not ok or idx + missing > len(avail):
            continue
        full = board + avail[idx: idx + missing]
        me = _evaluate(hole + full)
        best, ties = me, 1
        lost = False
        for o in opps:
            v = _evaluate(o + full)
            if v > best:
                lost = True
                break
            if v == best:
                ties += 1
        if not lost:
            total += 1.0 / ties
        n += 1
    return (total / n) if n else 0.5, n


def _v1_profiles(agent, state=None):
    p = agent.trackers.get("V1Profiles")
    if p is not None:
        p.me = state.get("seat", getattr(agent, "seat", None)) if state else getattr(agent, "seat", None)
        p.stack = int(agent.info.get("starting_stack", 2000) or 2000)
        if state:
            p.big_blind = int(S(state, "big_blind", p.big_blind) or p.big_blind)
    return p


def _v1_live_opps(state):
    me = state.get("seat")
    return [i for i, f in enumerate(state.get("folded") or []) if not f and i != me]


# ===========================================================================================
# HOOKS (layer 1 baseline + layer 3 responses, blended by the picker's knobs)
# ===========================================================================================
def hook_facing_allin(agent, state, ctx):
    """Delegate to the tournament shove-defense plug-in unless the jammer is confidently tight."""
    prof = _v1_profiles(agent, state)
    if prof is not None and S(state, "street") == "preflop":
        bets = S(state, "bets") or []
        if bets:
            jammer = max(range(len(bets)), key=lambda i: bets[i])
            k, w, label, st = prof.knobs(jammer)
            if w > 0.35 and k["jam_width"] < 0.3:
                key = _v1_key(*ctx["hole"])
                pct = _V1_PCT.get(key, 0.5)
                callers = sum(1 for i, b in enumerate(bets) if b >= bets[jammer] and i not in (jammer, state.get("seat")))
                limit = max(0.025, k["jam_width"] * (0.45 if callers == 0 else 0.25))
                if pct <= limit:
                    return {"action": "call"} if "call" in S(state, "legal_actions", []) else None
                return {"action": "fold"} if "fold" in S(state, "legal_actions", []) else None
    return _cand_facing_allin(agent, state, ctx)


def hook_preflop(agent, state, ctx):
    return _cand_preflop(agent, state, ctx)


def hook_betting(agent, state, ctx):
    """Nothing to call postflop. Multiway: tournament plug-in (+ P(all fold) bluff gate). Heads-up: v1 rules."""
    prof = _v1_profiles(agent, state)
    opps = _v1_live_opps(state)
    legal = S(state, "legal_actions", [])
    if "raise" not in legal:
        return None
    if len(opps) >= 2:
        return _cand_betting_mw(agent, state, ctx)
    if not opps:
        return None
    v = opps[0]
    k, w, label, st = prof.knobs(v) if prof else (dict(_V1_K0), 0.0, "unknown", IN_CHARACTER)
    deadline = ctx["started"] + _V1_MC_SECONDS
    eq, _ = _v1_equity(ctx["hole"], ctx["board"], [(1.0, 0.0)], agent.rng, deadline)
    ctx["v1_eq"] = eq
    if eq >= 0.62:
        frac = (0.66 if eq < 0.8 else 0.8) * k["value_mult"]
        return {"action": "raise", "amount": agent.size(state, ctx, "value", frac)}
    if eq < 0.35 and k["bluff_ok"] > 0.0:
        p_fold = prof.fold_prob(v) if prof else 0.45
        frac = 0.5
        need = frac / (1 + frac)
        if p_fold > need + 0.07 and agent.rng.random() < k["bluff_ok"]:
            return {"action": "raise", "amount": agent.size(state, ctx, "bluff", frac)}
    return {"action": "check"}


def hook_facing_bet(agent, state, ctx):
    """Facing a (non all-in) postflop bet: price exactly, equity vs the bettor's estimated range."""
    prof = _v1_profiles(agent, state)
    legal = S(state, "legal_actions", [])
    bets = S(state, "bets") or []
    pot = S(state, "pot")
    to_call = S(state, "to_call", 0) or 0
    if not bets or pot is None:
        return None
    me = state.get("seat")
    opps = _v1_live_opps(state)
    bettor = max(range(len(bets)), key=lambda i: bets[i])
    k, w, label, st = prof.knobs(bettor) if prof else (dict(_V1_K0), 0.0, "unknown", IN_CHARACTER)
    size_frac = to_call / max(1, pot - to_call)          # bet as a fraction of the pot before it
    base_f = 0.65 if size_frac <= 0.4 else (0.45 if size_frac <= 1.0 else 0.32)
    if S(state, "raises_this_street", 0) and S(state, "raises_this_street", 0) >= 2:
        base_f *= 0.6                                    # raise/re-raise: narrower
    f = max(0.04, min(1.0, base_f * k["bet_f"]))
    ranges = [(f, k["bluff_r"])] + [(0.7, 0.0) for o in opps if o != bettor][:3]  # cap work in big pots
    deadline = ctx["started"] + _V1_MC_SECONDS
    if time.perf_counter() - ctx["started"] > 0.005:
        return None                                       # time guard: fall back to the cheap default policy
    eq, _ = _v1_equity(ctx["hole"], ctx["board"], ranges, agent.rng, deadline)
    pot_odds = to_call / (pot + to_call)
    if eq >= 0.72 and "raise" in legal and len(opps) <= 2:
        frac = 0.75 * k["value_mult"]
        return {"action": "raise", "amount": agent.size(state, ctx, "raise_value", frac)}
    if eq >= pot_odds + 0.03:
        return {"action": "call"} if "call" in legal else {"action": "check"}
    return {"action": "fold"} if "fold" in legal else {"action": "check"}


def hook_sizing(agent, state, ctx, intent):
    """Pot-fraction sizes scaled by the table's value multiplier; near-stack sizes become all-in."""
    prof = _v1_profiles(agent, state)
    hi = state.get("max_raise_to")
    lo = state.get("min_raise_to")
    if hi is None or lo is None:
        return None
    base = {"value": 0.75, "thin_value": 0.55, "bluff": 0.5, "probe": 0.33,
            "raise_value": 0.75, "raise_bluff": 0.6}.get(intent, 0.6)
    mult = 1.0
    if prof is not None:
        opps = _v1_live_opps(state)
        if opps:
            mult = sum(prof.knobs(o)[0]["value_mult"] for o in opps) / len(opps)
    if intent in ("bluff", "probe", "raise_bluff"):
        mult = 1.0                                        # bluffs use standard sizes (no size tells)
    amt = pot_raise_to(state, base * mult)
    if amt is None:
        return None
    if amt >= 0.8 * hi:
        amt = hi
    return int(max(lo, min(hi, amt)))



def incumbent_policy(win_rate, state):
    legal = S(state, "legal_actions", [])
    if win_rate > 0.75 and "raise" in legal:
        bound = "max_raise_to" if win_rate > 0.85 else "min_raise_to"
        return {"action": "raise", "amount": int(state[bound])}
    if win_rate > 0.5 and "call" in legal:
        return {"action": "call"}
    if "check" in legal:
        return {"action": "check"}
    return {"action": "fold"}


class Agent:
    def __init__(self, *args, **kwargs):
        self.on_table_start({})

    def on_table_start(self, info):
        info = info or {}
        self.seat = int(info.get("seat", 0) or 0)
        self.rng = random.Random(2018 + self.seat)
        self.last_samples = 0
        self.stats = OpponentStats()
        self.trackers = {}
        for cls in EXTRA_TRACKERS:
            try:
                self.trackers[cls.__name__] = cls()
            except Exception:
                pass
        self.info = dict(info)
        for t in self.trackers.values():
            if hasattr(t, "me"):
                t.me = self.seat

    def size(self, state, ctx, intent, default_frac):
        amt = hook_sizing(self, state, ctx, intent)
        return int(amt) if amt is not None else pot_raise_to(state, default_frac)

    def observe(self, event):
        self._observe_seen = True
        self._feed(event)

    def _feed(self, event):
        self.stats.observe(event)
        for t in self.trackers.values():
            try:
                t.observe(event)
            except Exception:
                pass

    # --- kit event layer (AlgoSoc kit calls act() and on_hand_end(); never observe()) ---------------
    def _kit_new_hand(self, hid, n_seats):
        self._hist_hand, self._hist_n, self._hist_k, self._hist_street = hid, 0, 0, "preflop"
        self._feed({"type": "hand_start", "hand_id": hid, "stacks": [0] * n_seats})

    def _kit_replay(self, events, board):
        streets = ("preflop", "flop", "turn", "river")
        for ev in events:
            if not isinstance(ev, dict):
                continue
            st = ev.get("street", self._hist_street)
            if st != self._hist_street and st in streets:
                k = {"flop": 3, "turn": 4, "river": 5}.get(st, 0)
                self._feed({"type": "board", "hand_id": self._hist_hand, "street": st, "board": list(board[:k])})
                self._hist_street = st
            a = ev.get("action")
            if a in ("small_blind", "big_blind"):
                self._feed({"type": "action", "hand_id": self._hist_hand, "seat": ev.get("seat"), "street": "preflop",
                            "action": "post", "amount": ev.get("amount", 0)})
                continue
            self._hist_k += 1
            self._feed({"type": "action", "hand_id": self._hist_hand, "seat": ev.get("seat"), "street": st,
                        "action": a, "amount": ev.get("amount", 0)})

    def _ingest_history(self, state):
        """Replay new events from state history (kit format) into the trackers."""
        if getattr(self, "_observe_seen", False):
            return
        hist = S(state, "history") or []
        hid = state.get("hand_number", state.get("hand_id"))
        if hid != getattr(self, "_hist_hand", object()):
            self._kit_new_hand(hid, len(state.get("folded") or S(state, "stacks") or []))
        self._kit_replay(hist[self._hist_n:], state.get("board") or [])
        self._hist_n = len(hist)

    def on_hand_end(self, summary):
        try:
            if getattr(self, "_observe_seen", False) or not isinstance(summary, dict):
                return
            hid = summary.get("hand_number")
            stacks = summary.get("stacks") or []
            if hid != getattr(self, "_hist_hand", object()):
                self._kit_new_hand(hid, len(stacks))
            hist = [h for h in (summary.get("history") or []) if h.get("action") not in ("small_blind", "big_blind")]
            self._kit_replay(hist[self._hist_k:], summary.get("board") or [])
            if summary.get("board"):
                self._feed({"type": "board", "hand_id": hid, "street": "final", "board": list(summary["board"])})
            shown = summary.get("shown") or {}
            if shown:
                self._feed({"type": "showdown", "hand_id": hid,
                            "hands": {int(s): list(c) for s, c in shown.items() if c},
                            "winners": {int(w.get("seat")): w.get("amount", 0) for w in (summary.get("winners") or [])}})
            start = int(self.info.get("starting_stack", 0) or 0)
            self._feed({"type": "hand_end", "hand_id": hid,
                        "deltas": [int(x) - start for x in stacks] if start else []})
            self._hist_hand = ("ended", hid)
        except Exception:
            pass

    def act(self, state):
        try:
            self._ingest_history(state)
        except Exception:
            pass
        try:
            return sanitize(self._act(state), state)
        except Exception:
            return safe_default(state)

    def _act(self, state):
        started = time.perf_counter()
        hole = [_card(c) for c in S(state, "hole_cards")]
        board = [_card(c) for c in state.get("board", [])]
        opps = _remaining_opponents(state)
        ctx = {"hole": hole, "board": board, "opponents": opps, "started": started}
        stacks = S(state, "stacks")
        to_call = S(state, "to_call", 0) or 0
        me = state.get("seat", self.seat)
        my_stack = stacks[me] if stacks else None
        facing_allin = my_stack is not None and to_call > 0 and to_call >= 0.5 * my_stack
        if facing_allin:
            act = hook_facing_allin(self, state, ctx)
            if act is not None:
                return act
        street = S(state, "street") or ("preflop" if not board else "postflop")
        if street == "preflop":
            act = hook_preflop(self, state, ctx)
        elif to_call == 0:
            act = hook_betting(self, state, ctx)
        else:
            act = hook_facing_bet(self, state, ctx)
        if act is not None:
            return act
        win_rate, self.last_samples = _estimate_win_rate(hole, board, opps, self.rng,
                                                         deadline=started + THINK_SECONDS)
        ctx["win_rate"] = win_rate
        act = incumbent_policy(win_rate, state)
        if act.get("action") == "raise":
            intent = "value" if win_rate > 0.85 else "thin_value"
            amt = hook_sizing(self, state, ctx, intent)
            if amt is not None:
                act = {"action": "raise", "amount": int(amt)}
        return act
